			\onslide<4->{\node[paso, right=of b] (c) {Dividir\\$11\div45$};}
			\onslide<5->{\node[resultado, right=of c] (d) {$0.2\overline{4}$};}
			\onslide<4->{\node[verificacion, below=0.60cm of c] (e) {El residuo $20$ se repite.};}
			\onslide<1->{\draw[flecha] (a) -- (b);}
